function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(100 + i*100 + 50*Math.cos(t+i), 100 + 20*Math.sin(t+i), 20 + 10*Math.sin(t+i), 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W/2 - 20, H - 100, 40, 50);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 150, 50 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H - 50, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H - 50);
  ctx.lineTo(W/2 + 100, H - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H - 30);
  ctx.lineTo(W/2 + 120, H - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H - 30);
  ctx.lineTo(W/2 + 80, H - 40);
  ctx.stroke();

  ctx.restore();
}
